body{
  margin:0;
  padding:8px 4px;
  background:transparent;
  color:#ececef;
  font:13px/1.6 system-ui,-apple-system,'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif;
}

/* ==========================================
   主终端容器：点阵底纹 + 扫描线动画
   ========================================== */
main{
  position:relative;
  max-width:700px;
  margin:auto;
  padding:16px 18px 14px;
  background-color:#141416;
  background-image:
    linear-gradient(180deg,rgba(255,250,128,0.045) 0%,rgba(20,20,22,0) 64px),
    radial-gradient(rgba(255,255,255,0.03) 1px,transparent 0);
  background-size:100% 100%,16px 16px;
  border:1px solid #2c2c30;
  border-top:2px solid #fffa80;
  border-radius:2px;
  box-shadow:0 12px 32px rgba(0,0,0,0.5),0 0 20px rgba(255,250,128,0.04);
  overflow:hidden;
  animation:ef-boot .42s cubic-bezier(.16,1,.3,1) both;
}
@keyframes ef-boot{
  0%{opacity:0;transform:translateY(8px) scale(.992);border-top-color:#ffffff}
  100%{opacity:1;transform:translateY(0) scale(1);border-top-color:#fffa80}
}

/* 全息微弱扫描线 */
main::before{
  content:'';
  position:absolute;
  left:0;
  right:0;
  top:-120px;
  height:100px;
  background:linear-gradient(180deg,transparent 0%,rgba(255,250,128,0.024) 85%,rgba(255,250,128,0.07) 100%);
  pointer-events:none;
  z-index:1;
  animation:ef-scanline 8.5s linear infinite;
}
@keyframes ef-scanline{
  0%{transform:translateY(0)}
  100%{transform:translateY(900px)}
}

/* 右下角终末地折角呼吸灯 */
main::after{
  content:'';
  position:absolute;
  bottom:0;
  right:0;
  width:12px;
  height:12px;
  border-right:2px solid #fffa80;
  border-bottom:2px solid #fffa80;
  pointer-events:none;
  z-index:3;
  animation:ef-corner-breathe 3s ease-in-out infinite;
}
@keyframes ef-corner-breathe{
  0%,100%{opacity:.55;box-shadow:none}
  50%{opacity:1;box-shadow:2px 2px 8px rgba(255,250,128,0.35)}
}

/* ==========================================
   顶部连接状态角标 & 标题栏
   ========================================== */
.ef-top-connect{
  position:absolute;
  top:14px;
  right:18px;
  z-index:3;
  display:inline-flex;
  align-items:center;
  gap:5px;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:11px;
  color:#fffa80;
  background:rgba(255,250,128,0.07);
  border:1px solid rgba(255,250,128,0.28);
  padding:1px 8px;
  border-radius:1px;
  letter-spacing:.6px;
  pointer-events:none;
  white-space:nowrap;
}
.ef-top-connect::before{
  content:'';
  width:6px;
  height:6px;
  border-radius:50%;
  background:#7ef0b8;
  box-shadow:0 0 6px #7ef0b8;
  animation:ef-led-pulse 1.8s ease-in-out infinite;
}
@keyframes ef-led-pulse{
  0%,100%{opacity:1;transform:scale(1)}
  50%{opacity:.4;transform:scale(.85)}
}
.ef-top-dots{
  display:inline-block;
  width:18px;
  text-align:left;
}

#step{
  position:relative;
  z-index:2;
  margin:0 0 2px;
  padding-right:160px;
  color:#fffa80;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:11.5px;
  font-weight:700;
  letter-spacing:.08em;
}
#step::before{
  content:'AIC-PROTOCOL // ';
  color:#71717a;
  font-weight:600;
}

h2{
  position:relative;
  z-index:2;
  margin:0 0 10px;
  padding:2px 0 10px;
  font-size:18px;
  font-weight:700;
  letter-spacing:.6px;
  color:#f4f4f5;
  border-bottom:1px solid #27272b;
  background-repeat:no-repeat;
  background-position:0 100%;
  background-size:25% 2px;
  background-image:linear-gradient(90deg,#fffa80,#ffffb8);
  transition:background-size .35s cubic-bezier(.22,1,.36,1);
}
main:has(#page0:not([hidden])) h2{background-size:25% 2px}
main:has(#page1:not([hidden])) h2{background-size:50% 2px}
main:has(#page2:not([hidden])) h2{background-size:75% 2px}
main:has(#page3:not([hidden])) h2{background-size:100% 2px}

/* ==========================================
   四段式战术步骤指示器 (斜切柔光带与遥测流场)
   ========================================== */
.ef-stepper{
  position:relative;
  z-index:2;
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:6px;
  margin:0 0 10px;
}
.ef-step-item{
  position:relative;
  z-index:1;
  padding:6px 10px;
  background:#18181b;
  border:1px solid #27272b;
  border-left:2px solid #3f3f46;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:11px;
  color:#71717a;
  letter-spacing:.4px;
  overflow:hidden;
  transition:border-color .25s ease,color .25s ease,box-shadow .25s ease,background-color .25s ease;
}
/* 200% 宽全高贯穿斜切流光层：保持同样丝滑流速，无拼块无波浪 */
.ef-step-item::before{
  content:'';
  position:absolute;
  top:0;
  left:0;
  width:200%;
  height:100%;
  background-image:var(--ef-flow-yellow);
  background-size:100% 100%;
  background-repeat:no-repeat;
  opacity:.18;
  pointer-events:none;
  z-index:-1;
  transition:opacity .3s ease;
}
.ef-step-item b{
  display:block;
  font-size:10px;
  color:#52525b;
  font-weight:700;
}

/* 连续单向流动动画（保持 6.5s 舒适流速） */
@keyframes ef-tech-flow{
  0%{transform:translate3d(0,0,0)}
  100%{transform:translate3d(-50%,0,0)}
}

/* 当前激活步骤 */
main:has(#page0:not([hidden])) .ef-step-item:nth-child(1),
main:has(#page1:not([hidden])) .ef-step-item:nth-child(2),
main:has(#page2:not([hidden])) .ef-step-item:nth-child(3),
main:has(#page3:not([hidden])) .ef-step-item:nth-child(4){
  color:#fffa80;
  border-color:rgba(255,250,128,0.5);
  border-left:2px solid #fffa80;
  background-color:#1c1c1f;
  background-image:linear-gradient(90deg,rgba(255,250,128,0.11) 0%,rgba(255,250,128,0.02) 70%,transparent 100%);
  box-shadow:0 0 14px rgba(255,250,128,0.09);
}
main:has(#page0:not([hidden])) .ef-step-item:nth-child(1)::before,
main:has(#page1:not([hidden])) .ef-step-item:nth-child(2)::before,
main:has(#page2:not([hidden])) .ef-step-item:nth-child(3)::before,
main:has(#page3:not([hidden])) .ef-step-item:nth-child(4)::before{
  opacity:1;
  animation:ef-tech-flow 6.5s linear infinite;
}
main:has(#page0:not([hidden])) .ef-step-item:nth-child(1) b,
main:has(#page1:not([hidden])) .ef-step-item:nth-child(2) b,
main:has(#page2:not([hidden])) .ef-step-item:nth-child(3) b,
main:has(#page3:not([hidden])) .ef-step-item:nth-child(4) b{
  color:#fffa80;
}

/* 已完成步骤样式：翠绿斜切流光 */
main:has(#page1:not([hidden])) .ef-step-item:nth-child(1),
main:has(#page2:not([hidden])) .ef-step-item:nth-child(-n+2),
main:has(#page3:not([hidden])) .ef-step-item:nth-child(-n+3){
  color:#d4d4d8;
  border-color:#323238;
  border-left:2px solid #7ef0b8;
  background-color:#171c1a;
  background-image:linear-gradient(90deg,rgba(126,240,184,0.08) 0%,transparent 75%);
}
main:has(#page1:not([hidden])) .ef-step-item:nth-child(1)::before,
main:has(#page2:not([hidden])) .ef-step-item:nth-child(-n+2)::before,
main:has(#page3:not([hidden])) .ef-step-item:nth-child(-n+3)::before{
  background-image:var(--ef-flow-green);
  opacity:.85;
  animation:ef-tech-flow 10s linear infinite;
}
main:has(#page1:not([hidden])) .ef-step-item:nth-child(1) b,
main:has(#page2:not([hidden])) .ef-step-item:nth-child(-n+2) b,
main:has(#page3:not([hidden])) .ef-step-item:nth-child(-n+3) b{
  color:#7ef0b8;
}

/* ==========================================
   打字机干员通讯栏
   ========================================== */
.ef-note{
  position:relative;
  z-index:2;
  margin:0 0 10px;
  color:#a1a1aa;
  font-size:12px;
  display:flex;
  align-items:center;
  gap:6px;
  min-height:22px;
}
.ef-note-tag{
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:10.5px;
  color:#fffa80;
  opacity:.9;
  letter-spacing:.5px;
  background:rgba(255,250,128,0.08);
  padding:0 5px;
  border:1px solid rgba(255,250,128,0.28);
  flex-shrink:0;
}
.ef-cursor{
  display:inline-block;
  width:6px;
  height:12px;
  background:#fffa80;
  margin-left:3px;
  vertical-align:middle;
  animation:ef-blink .75s infinite;
}
@keyframes ef-blink{
  0%,49%{opacity:1}
  50%,100%{opacity:0}
}

/* ==========================================
   页面切换动画与说明栏
   ========================================== */
section{
  position:relative;
  z-index:2;
}
section:not([hidden]){
  animation:ef-page-enter .28s cubic-bezier(.22,1,.36,1) both;
}
@keyframes ef-page-enter{
  0%{opacity:0;transform:translateY(6px)}
  100%{opacity:1;transform:translateY(0)}
}

p{
  color:#a1a1aa;
  font-size:12.5px;
  line-height:1.65;
}
section>p{
  margin:0 0 10px;
  padding:7px 11px;
  background:#1b1b1e;
  border:1px solid #2a2a2f;
  border-left:2px solid #fffa80;
  color:#c4c4cc;
}
section>p::before{
  content:'DIRECTIVE //';
  display:inline-block;
  margin-right:7px;
  padding:0 5px;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:10.5px;
  color:#fffa80;
  background:rgba(255,250,128,0.08);
  border:1px solid rgba(255,250,128,0.28);
  letter-spacing:.5px;
}

/* ==========================================
   表单输入控件与自定义滚动条
   ========================================== */
input,textarea,button{font:inherit}
input,textarea{
  padding:8px 11px;
  color:#f4f4f5;
  background:#101012;
  border:1px solid #2e2e34;
  border-radius:1px;
  transition:border-color .2s ease,box-shadow .2s ease,background-color .2s ease;
}
input::placeholder,textarea::placeholder{color:#71717a}
input:focus,textarea:focus{
  outline:none;
  border-color:#fffa80;
  background:#131316;
  box-shadow:0 0 0 1px rgba(255,250,128,0.25),inset 2px 0 0 #fffa80,0 0 14px rgba(255,250,128,0.08);
}
input:focus-visible,textarea:focus-visible,button:focus-visible{
  outline:2px solid #ffffd5;
  outline-offset:2px;
}
#search,textarea{width:100%}
textarea{
  min-height:180px;
  resize:vertical;
  line-height:1.7;
}
#people,#favor,pre,textarea{
  scrollbar-width:thin;
  scrollbar-color:#484852 #18181b;
}
#people::-webkit-scrollbar,#favor::-webkit-scrollbar,pre::-webkit-scrollbar,textarea::-webkit-scrollbar{
  width:6px;
  height:6px;
}
#people::-webkit-scrollbar-track,#favor::-webkit-scrollbar-track,pre::-webkit-scrollbar-track,textarea::-webkit-scrollbar-track{
  background:#18181b;
}
#people::-webkit-scrollbar-thumb,#favor::-webkit-scrollbar-thumb,pre::-webkit-scrollbar-thumb,textarea::-webkit-scrollbar-thumb{
  background:#484852;
  border-radius:1px;
}
#people::-webkit-scrollbar-thumb:hover,#favor::-webkit-scrollbar-thumb:hover,pre::-webkit-scrollbar-thumb:hover,textarea::-webkit-scrollbar-thumb:hover{
  background:#fffa80;
}

/* ==========================================
   干员编成战术网格 & 斜切流光 & 英文代号映射 (#people)
   ========================================== */


/* ==========================================
   干员编成官网卡牌网格 (#people) — 官网 Operator 风格
   ========================================== */
#people{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(136px,1fr));
  gap:10px;
  overflow:visible;
  margin-top:10px;
  padding:12px;
  background:#141416;
  border:1px solid #28282d;
}
.row{
  display:flex;
  align-items:center;
  gap:8px;
  padding:9px 12px;
  border-bottom:1px solid #232327;
  transition:background-color .18s ease,border-color .18s ease,transform .18s cubic-bezier(.22,1,.36,1),box-shadow .18s ease;
}

/* 官网卡片基础骨架：高宽比严格匹配官网切图 (412:526) */
#people .row{
  position:relative;
  filter:brightness(0.72) contrast(1.05);
  z-index:1;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  align-items:flex-start;
  aspect-ratio:412/526;
  min-height:172px;
  padding:8px 8px 6px;
  background-color:#1c1c20;
  background-image:var(--ef-card-pic,none);
  background-size:cover;
  background-position:center top;
  background-repeat:no-repeat;
  border:1px solid #2f2f36;
  border-bottom:2px solid #3f3f46;
  border-radius:1px;
  cursor:pointer;
  user-select:none;
  overflow:hidden;
  box-shadow:0 3px 8px rgba(0,0,0,0.35);
  image-rendering:-webkit-optimize-contrast;
  image-rendering:crisp-edges;
  transition:border-color .2s ease,transform .2s cubic-bezier(.22,1,.36,1),box-shadow .2s ease;
}

/* 卡片悬浮态：上浮微动效 + 终末地明黄边缘泛光 */
#people .row:hover{
  filter:brightness(0.9) contrast(1.02);
  border-color:#fffa80;
  border-bottom-color:#fffa80;
  transform:translateY(-2px);
  box-shadow:0 6px 16px rgba(0,0,0,0.5),0 0 10px rgba(255,250,128,0.25);
  z-index:2;
}

/* 左上角战术勾选框：浮于卡片顶层 */
#people .row input[type=checkbox]{
  position:relative;
  z-index:4;
  margin:0;
  box-shadow:0 0 6px rgba(0,0,0,0.8);
}

/* 卡片底部名称条：未配图干员保底展示 */
#people .row span{
  position:relative;
  z-index:3;
  width:100%;
  margin-top:auto;
  padding:4px 6px;
  background:rgba(20,20,22,0.88);
  backdrop-filter:blur(2px);
  border-top:1px solid rgba(255,250,128,0.25);
  color:#f4f4f5;
  font-size:12.5px;
  font-weight:700;
  letter-spacing:.5px;
  text-align:left;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  transition:background .2s ease,color .2s ease;
}

/* 卡片右上角状态标识 */
#people .row::after{
  content:var(--ef-code,'STBY');
  position:absolute;
  top:6px;
  right:6px;
  z-index:3;
  padding:1px 5px;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:9.5px;
  letter-spacing:.4px;
  color:#a1a1aa;
  background:rgba(18,18,20,0.85);
  border:1px solid #383840;
  border-radius:1px;
  box-shadow:0 0 4px rgba(0,0,0,0.6);
  opacity:0;
  transform:translateY(-2px);
  transition:all .18s ease;
}
#people .row:hover::after{
  opacity:1;
  transform:translateY(0);
  color:#fffa80;
  border-color:rgba(255,250,128,0.4);
}

/* 卡片选中激活态 */
#people .row:has(input:checked){
  filter:brightness(1) contrast(1);
  border:1.5px solid #fffa80;
  border-bottom:3px solid #fffa80;
  box-shadow:0 0 14px rgba(255,250,128,0.35),0 4px 12px rgba(0,0,0,0.6);
}
#people .row:has(input:checked)::after{
  content:'● ' var(--ef-code,'ON');
  opacity:1;
  transform:translateY(0);
  color:#7ef0b8;
  border-color:rgba(126,240,184,0.5);
  background:rgba(18,24,20,0.9);
  font-weight:700;
  text-shadow:0 0 6px rgba(126,240,184,0.45);
}
#people .row:has(input:checked) span{
  color:#fffa80;
  border-top-color:#fffa80;
}

/* ==========================================
   好感度校准官网卡牌网格 (#favor) — STEP 02 延用官网卡牌
   ========================================== */
#favor{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(136px,1fr));
  gap:10px;
  overflow:visible;
  margin-top:10px;
  padding:12px;
  background:#141416;
  border:1px solid #28282d;
}
#favor:empty{
  display:block;
}
#favor:empty::before{
  content:'当前未选择在场干员 // 本局将以无预设在场角色模式启动，可直接点击「下一步」。';
  display:block;
  padding:28px 14px;
  text-align:center;
  color:#8e8e96;
  font-size:12.5px;
}
#favor .row{
  position:relative;
  filter:brightness(0.85) contrast(1.02);
  z-index:1;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  align-items:flex-start;
  aspect-ratio:412/526;
  min-height:172px;
  padding:8px 8px 6px;
  background-color:#1c1c20;
  background-image:var(--ef-card-pic,none);
  background-size:cover;
  background-position:center top;
  background-repeat:no-repeat;
  border:1px solid #2f2f36;
  border-bottom:2px solid #3f3f46;
  border-radius:1px;
  overflow:hidden;
  box-shadow:0 3px 8px rgba(0,0,0,0.35);
  image-rendering:-webkit-optimize-contrast;
  image-rendering:crisp-edges;
  transition:border-color .2s ease,transform .2s cubic-bezier(.22,1,.36,1),box-shadow .2s ease;
}
#favor .row:hover,#favor .row:focus-within{
  filter:brightness(1) contrast(1);
  border-color:#fffa80;
  border-bottom-color:#fffa80;
  transform:translateY(-2px);
  box-shadow:0 6px 16px rgba(0,0,0,0.5),0 0 10px rgba(255,250,128,0.25);
  z-index:2;
}

/* 右上角干员代号标（与 STEP 01 统一） */
#favor .row::after{
  content:var(--ef-code,'AFFINITY');
  position:absolute;
  top:6px;
  right:6px;
  z-index:3;
  padding:1px 5px;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:9.5px;
  letter-spacing:.4px;
  color:#fffa80;
  background:rgba(18,18,20,0.88);
  border:1px solid rgba(255,250,128,0.35);
  border-radius:1px;
  box-shadow:0 0 4px rgba(0,0,0,0.6);
}

/* 左上角 AFFINITY // 战术小标 */
#favor .row::before{
  content:'AFFINITY //';
  position:absolute;
  top:6px;
  left:8px;
  z-index:3;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:9px;
  color:#a1a1aa;
  letter-spacing:.5px;
  text-shadow:0 0 4px rgba(0,0,0,0.9);
}
#favor .row:hover::before,#favor .row:focus-within::before{
  color:#fffa80;
}

/* 卡片中央名称（未配图展示） */
#favor .row span{
  display:block;
  position:relative;
  z-index:3;
  width:100%;
  margin-top:auto;
  margin-bottom:6px;
  padding:3px 6px;
  background:rgba(20,20,22,0.85);
  backdrop-filter:blur(2px);
  border-top:1px solid rgba(255,250,128,0.2);
  color:#f4f4f5;
  font-size:12px;
  font-weight:700;
  letter-spacing:.5px;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

/* STEP 02 底部嵌入式好感度输入条 */
#favor .row input[type=number]{
  position:relative;
  z-index:4;
  width:100%;
  margin-top:auto;
  padding:4px 8px;
  text-align:center;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:13px;
  font-weight:700;
  color:#fffa80;
  background:rgba(16,16,18,0.92);
  backdrop-filter:blur(3px);
  border:1px solid #3a3a44;
  border-bottom:2px solid #fffa80;
  border-radius:1px;
  box-shadow:0 2px 6px rgba(0,0,0,0.5);
  transition:border-color .15s ease,box-shadow .15s ease,background .15s ease;
}
#favor .row input[type=number]:focus{
  outline:none;
  border-color:#fffa80;
  background:#141418;
  box-shadow:0 0 10px rgba(255,250,128,0.35);
}

/* ==========================================
   重要特殊 NPC（阿达希尔、聂菲斯）独立样式与底栏隔离
   ========================================== */
#people .row[data-search^="阿达希尔"],
#people .row[data-search^="聂菲斯"],
#favor .row[data-search^="阿达希尔"],
#favor .row[data-search^="聂菲斯"]{
  grid-column:1/-1!important;
  aspect-ratio:auto!important;
  min-height:44px!important;
  height:auto!important;
  display:flex!important;
  flex-direction:row!important;
  align-items:center!important;
  justify-content:flex-start!important;
  gap:10px!important;
  padding:6px 14px!important;
  background:#1b1b1f!important;
  background-image:linear-gradient(90deg,rgba(255,80,80,0.06) 0%,transparent 60%)!important;
  border:1px solid #3c2a2e!important;
  border-left:3px solid #ff6363!important;
  border-radius:1px!important;
  box-shadow:none!important;
  filter:none!important;
  order:9999!important;
}

/* 彻底清除 NPC 元素在 STEP 02 继承的通用卡片 AFFINITY // 伪元素 */
#favor .row[data-search^="聂菲斯"]::before,
#people .row[data-search^="聂菲斯"]::before{
  content:none!important;
  display:none!important;
}

/* 顶部细分隔线与 // SPECIAL NPC // 标志（绑定在阿达希尔顶端） */
#people .row[data-search^="阿达希尔"],
#favor .row[data-search^="阿达希尔"]{
  margin-top:14px!important;
  order:9998!important;
}
#people .row[data-search^="阿达希尔"]::before,
#favor .row[data-search^="阿达希尔"]::before{
  content:'// SPECIAL NPC //';
  position:absolute;
  top:-16px;
  left:0;
  right:0;
  display:flex;
  align-items:center;
  gap:10px;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:10px;
  font-weight:700;
  color:#ff8585;
  letter-spacing:.8px;
  text-shadow:none;
  pointer-events:none;
}
#people .row[data-search^="阿达希尔"]::before::after,
#favor .row[data-search^="阿达希尔"]::before::after{
  content:'';
  flex:1;
  height:1px;
  background:linear-gradient(90deg,rgba(255,99,99,0.5) 0%,transparent 100%);
}

#people .row[data-search^="聂菲斯"],
#favor .row[data-search^="聂菲斯"]{
  margin-top:0!important;
  order:9999!important;
}

/* 悬浮与选中态 */
#people .row[data-search^="阿达希尔"]:hover,
#people .row[data-search^="聂菲斯"]:hover,
#favor .row[data-search^="阿达希尔"]:hover,
#favor .row[data-search^="聂菲斯"]:hover{
  background:#232024!important;
  border-color:#ff6363!important;
  transform:none!important;
  box-shadow:0 0 10px rgba(255,99,99,0.25)!important;
}

#people .row[data-search^="阿达希尔"]:has(input:checked),
#people .row[data-search^="聂菲斯"]:has(input:checked){
  background:rgba(255,99,99,0.12)!important;
  border-color:#ff6363!important;
  border-left:3px solid #ff6363!important;
  box-shadow:0 0 12px rgba(255,99,99,0.3)!important;
}

/* 文字与控件还原 - 彻底解决 STEP 02 重叠 */
#people .row[data-search^="阿达希尔"] span,
#people .row[data-search^="聂菲斯"] span,
#favor .row[data-search^="阿达希尔"] span,
#favor .row[data-search^="聂菲斯"] span{
  display:inline-block!important;
  position:static!important;
  width:auto!important;
  margin:0!important;
  padding:0 0 0 8px!important;
  background:transparent!important;
  border:none!important;
  color:#f4f4f5!important;
  font-weight:650!important;
  flex:1 1 auto!important;
  text-align:left!important;
}

#people .row[data-search^="阿达希尔"] input[type=checkbox],
#people .row[data-search^="聂菲斯"] input[type=checkbox]{
  position:static!important;
  box-shadow:none!important;
  flex-shrink:0!important;
}

#favor .row[data-search^="阿达希尔"] input[type=number],
#favor .row[data-search^="聂菲斯"] input[type=number]{
  position:static!important;
  width:96px!important;
  height:30px!important;
  margin:0!important;
  padding:3px 8px!important;
  flex-shrink:0!important;
  text-align:center!important;
  font-size:13px!important;
}

#people .row[data-search^="阿达希尔"]::after,
#favor .row[data-search^="阿达希尔"]::after{
  content:'NPC // Ardashir'!important;
  position:static!important;
  margin:0 4px 0 auto!important;
  color:#ff8585!important;
  background:rgba(255,99,99,0.1)!important;
  border:1px solid rgba(255,99,99,0.3)!important;
  border-radius:1px!important;
  padding:1px 6px!important;
  font-size:9.5px!important;
  letter-spacing:.4px!important;
  opacity:0.9!important;
  transform:none!important;
  flex-shrink:0!important;
}

#people .row[data-search^="聂菲斯"]::after,
#favor .row[data-search^="聂菲斯"]::after{
  content:'NPC // Nephthys'!important;
  position:static!important;
  margin:0 4px 0 auto!important;
  color:#ff8585!important;
  background:rgba(255,99,99,0.1)!important;
