/* ==========================================
   STEP 02 批量好感度快捷工具栏 (Batch Toolbar)
   ========================================== */
.ef-batch-toolbar{
  display:flex;
  align-items:center;
  justify-content:space-between;
  flex-wrap:wrap;
  gap:10px;
  margin:10px 0 14px 0;
  padding:8px 12px;
  background:rgba(22,22,26,0.95);
  border:1px solid #323238;
  border-left:3px solid #fffa80;
  border-radius:1px;
  box-shadow:0 2px 8px rgba(0,0,0,0.4);
}
.ef-batch-label{
  display:flex;
  align-items:center;
  gap:8px;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:11px;
}
.ef-batch-tag{
  color:#fffa80;
  font-weight:700;
  letter-spacing:.5px;
}
.ef-batch-count{
  color:#a1a1aa;
  transition:color .15s ease;
}
.ef-batch-count.has-selection{
  color:#fffa80;
  font-weight:600;
  text-shadow:0 0 6px rgba(255,250,128,0.35);
}
.ef-batch-actions{
  display:flex;
  align-items:center;
  gap:8px;
  margin-left:auto;
}
.ef-batch-input-wrap{
  position:relative;
  display:flex;
  align-items:center;
}
.ef-batch-input-wrap input[type=number]{
  width:125px!important;
  height:28px!important;
  padding:2px 8px!important;
  text-align:center!important;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace!important;
  font-size:12px!important;
  font-weight:700!important;
  color:#fffa80!important;
  background:#141418!important;
  border:1px solid #3f3f46!important;
  border-bottom:2px solid #fffa80!important;
  border-radius:1px!important;
  outline:none!important;
  margin:0!important;
}
.ef-batch-input-wrap input[type=number]:focus{
  border-color:#fffa80!important;
  box-shadow:0 0 8px rgba(255,250,128,0.3)!important;
}
.ef-batch-btn{
  height:28px;
  padding:0 12px;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  font-size:11px;
  font-weight:650;
  letter-spacing:.4px;
  cursor:pointer;
  border-radius:1px;
  transition:all .15s ease;
}
.ef-batch-btn.primary{
  background:#fffa80;
  color:#121214;
  border:1px solid #fffa80;
  box-shadow:0 0 6px rgba(255,250,128,0.25);
}
.ef-batch-btn.primary:hover{
  background:#fff;
  border-color:#fff;
  box-shadow:0 0 10px rgba(255,255,255,0.4);
}
.ef-batch-btn.secondary{
  background:#1f1f23;
  color:#d4d4d8;
  border:1px solid #3f3f46;
}
.ef-batch-btn.secondary:hover{
  background:#27272a;
  border-color:#71717a;
  color:#fff;
}

/* STEP 02 卡片选中激活态（复选高亮，与 STEP 01 统一） */
#favor .row{
  cursor:pointer;
  user-select:none;
}
#favor .row input[type=number]{
  cursor:text;
  user-select:auto;
}
#favor .row.is-selected{
  filter:brightness(1) contrast(1)!important;
  border:1.5px solid #fffa80!important;
  border-bottom:3px solid #fffa80!important;
  box-shadow:0 0 14px rgba(255,250,128,0.35),0 4px 12px rgba(0,0,0,0.6)!important;
}
#favor .row.is-selected::after{
  content:'● ' var(--ef-code,'ON')!important;
  opacity:1!important;
  transform:translateY(0)!important;
  color:#7ef0b8!important;
  border-color:rgba(126,240,184,0.5)!important;
  background:rgba(18,24,20,0.9)!important;
  font-weight:700!important;
  text-shadow:0 0 6px rgba(126,240,184,0.45)!important;
}
#favor .row.is-selected::before{
  color:#fffa80!important;
  text-shadow:0 0 6px rgba(255,250,128,0.6)!important;
}
#favor .row.is-selected span{
  color:#fffa80!important;
  border-top-color:#fffa80!important;
}
#favor .row.is-selected input[type=number]{
  border-color:#fffa80!important;
  box-shadow:0 0 8px rgba(255,250,128,0.3)!important;
}

/* 特殊 NPC（阿达希尔、聂菲斯）在 STEP 02 选中态 */
#favor .row[data-search^="阿达希尔"].is-selected,
#favor .row[data-search^="聂菲斯"].is-selected{
  background:rgba(255,99,99,0.18)!important;
  border-color:#ff6363!important;
  border-left:4px solid #ff6363!important;
  box-shadow:0 0 14px rgba(255,99,99,0.4)!important;
}
#favor .row[data-search^="阿达希尔"].is-selected span,
#favor .row[data-search^="聂菲斯"].is-selected span{
  color:#ff9e9e!important;
}
#favor .row[data-search^="阿达希尔"].is-selected::after,
#favor .row[data-search^="聂菲斯"].is-selected::after{
  border-color:rgba(255,99,99,0.6)!important;
  background:rgba(255,99,99,0.2)!important;
  box-shadow:0 0 8px rgba(255,99,99,0.4)!important;
}

/* 彻底清除各类浏览器原生微调按钮与箭头（解决 STEP 02 重叠问题） */
input[type=number]::-webkit-inner-spin-button,
input[type=number]::-webkit-outer-spin-button{
  -webkit-appearance:none!important;
  margin:0!important;
}
input[type=number]{
  -moz-appearance:textfield!important;
  appearance:textfield!important;
}


