// 纯视觉装饰层动画（独立运行，不触碰任何数据层逻辑）
(()=>{
  const notes=[
    "终末地危机处理小组已就绪。",
    "我收到来自您的信号了。我正在释读它的含义，请稍等。",
    "我从宏山述职回来，给你带了些礼物，不是很贵重，但……都是精心挑选过的，希望你能喜欢。",
    "如果陪着我的人是您的话……就让人放心多了。",
    "Z7行动组，秋栗，很高兴加入这次行动！请期待我的表现！",
    "我的“远征”尚未结束……",
    "风不会停下，我也不会。",
    "出门在外要有计划的，别乱跑，别乱吃，也别乱说话。"
  ];
  const noteEl=document.getElementById('ef-note-text');
  const dotsEl=document.getElementById('ef-dots');
  if(dotsEl){
    const states=['','.','..','...'];
    let d=0;
    setInterval(()=>{d=(d+1)%states.length;dotsEl.textContent=states[d];},550);
  }
  if(noteEl){
    let idx=0,char=notes[0].length,del=true;
    const tick=()=>{
      const s=notes[idx];
      if(!del){
        char++;
        noteEl.textContent=s.slice(0,char);
        setTimeout(tick,char>=s.length?(del=true,3000):48);
      }else{
        char--;
        noteEl.textContent=s.slice(0,char);
        if(char<=0){del=false;idx=(idx+1)%notes.length;setTimeout(tick,380);}
        else setTimeout(tick,24);
      }
    };
    setTimeout(tick,2600);
  }
})();
</script>
<script>
(async()=>{
const BOOK='エンドフィールド v2.0';
const ROSTER='【变量】干员｜共用名单';
const META='endfield_opening_setup_v1';
const scope={type:'message',message_id:0};
const el=id=>document.getElementById(id);
const selected=new Set();
const favorSelected=new Set();
const values=new Map();
const configured=new Set();
let roster=[],page=0,busy=false,ready=false;

function openingOnly(){
  if(getCurrentMessageId()!==0||getLastMessageId()!==0)
    throw Error('只支持尚未开始聊天的第0楼。请使用新聊天。');
}
async function read(){
  const data=await Mvu.getMvuData(scope);
  if(!data?.stat_data?.角色||!Object.keys(data.stat_data.角色).length)
    throw Error('第0楼变量尚未初始化，请稍后重新加载。');
  return data;
}
function inputBox(){
  // 与本机SillyTavern的/setinput使用同一输入框。
  const box=window.parent.document.getElementById('send_textarea');
  if(!box)throw Error('找不到酒馆聊天输入框。');
  return box;
}
function chosen(){
  return roster.filter(person=>selected.has(person.名字));
}
function validate(){
  for(const person of roster.filter(person=>configured.has(person.名字))){
  const value = values.get(person.名字);
  if (!Number.isSafeInteger(value))
    throw Error(person.名字 + '：好感度请输入有效整数。');

  values.set(person.名字, Math.max(-100, Math.min(100, value)));
  }
}
function buildText(){
  validate();
  return [
    '【本次自定义开局】',
    '本次开场实际在场的角色：',
    ...(chosen().length?chosen().map(person=>'- '+person.名字):['无（以无人出场开局）。']),
    '',
    '初始好感度设置（不代表角色出场）：',
    ...((roster.filter(person=>configured.has(person.名字)||selected.has(person.名字)))
      .map(person=>'- '+person.名字+'：'+values.get(person.名字)+'；'
        +(selected.has(person.名字)?'开场在场':'开场不在场'))),
    '未列出的角色保留原有好感度。未列入出场名单的角色，不因这里提及而出场。',
    '',
    '开局大纲：',
    el('outline').value.trim(),
    '',
    '请根据以上设定开始剧情，并保持角色原有人格与知情边界。',
    '好感度表示已有关系基础，不代表无条件服从或自动成为恋人。',
    '不要复述设置清单，也不要将本次初始好感度当作本轮事件再次加算。'
  ].join('\n');
}
function updateBatchToolbar(){
  const countEl=el('favor-batch-count');
  if(!countEl)return;
  const size=favorSelected.size;
  if(size===0){
    countEl.textContent='点击卡片可多选（未选）';
    countEl.classList.remove('has-selection');
  }else{
    countEl.textContent='已选择 '+size+' 位角色';
    countEl.classList.add('has-selection');
  }
}
function updateSearch(){
  const query=el('search').value.trim().toLocaleLowerCase();
  for(const row of el('people').children)
    row.hidden=!row.dataset.search.includes(query);
}
function renderPeople(){
  el('people').replaceChildren();
  for(const person of roster){
    const label=document.createElement('label');
    label.className='row';
    const aliases=Array.isArray(person.称呼)?person.称呼:[];
    label.dataset.search=[person.名字,...aliases].join(' ').toLocaleLowerCase();
    const checkbox=document.createElement('input');
    checkbox.type='checkbox';
    checkbox.checked=selected.has(person.名字);
    checkbox.addEventListener('change',()=>{
      if(checkbox.checked)selected.add(person.名字);
      else selected.delete(person.名字);
      el('status').textContent='已选择'+selected.size+'位角色。';
    });
    const text=document.createElement('span');
    text.textContent=person.名字;
    label.append(checkbox,text);
    el('people').append(label);
  }
  updateSearch();
}
function updateFavorSearch(){
  const query=el('favor-search').value.trim().toLocaleLowerCase();
  for(const row of el('favor').children)
    row.hidden=!row.dataset.search.includes(query);
}
function renderFavor(){
  el('favor').replaceChildren();
  for(const person of roster){
    const card=document.createElement('div');
    card.className='row';
    card.dataset.person=person.名字;
    const text=document.createElement('span');
    text.textContent=person.名字;
    const aliases=Array.isArray(person.称呼)?person.称呼:[];
    card.dataset.search=[person.名字,...aliases].join(' ').toLocaleLowerCase();
    const input=document.createElement('input');
    input.type='number';input.step='1';
    const value=values.get(person.名字);
    input.value=Number.isFinite(value)?String(value):'';
    input.setAttribute('aria-label',person.名字+'初始好感度');
    input.min = '-100';
    input.max = '100';

    input.addEventListener('input', () => {
      configured.add(person.名字);
      if (input.value.trim() === '') {
        values.set(person.名字, NaN);
        return;
      }

      const value = Math.max(-100, Math.min(100, Number(input.value)));
      values.set(person.名字, value);

      if (Number(input.value) !== value) {
        input.value = String(value);
      }
    });

    if(favorSelected.has(person.名字)){
      card.classList.add('is-selected');
    }

    card.addEventListener('click', (e) => {
      if(e.target === input) return;
      e.preventDefault();
      e.stopPropagation();

      const name = person.名字;
      if(favorSelected.has(name)){
        favorSelected.delete(name);
        card.classList.remove('is-selected');
      }else{
        favorSelected.add(name);
        card.classList.add('is-selected');
      }
      updateBatchToolbar();
    });

    card.append(text,input);
    el('favor').append(card);
  }
  updateFavorSearch();
  updateBatchToolbar();
}
function show(){
  for(let i=0;i<4;i++)el('page'+i).hidden=i!==page;
  el('title').textContent=['选择出场角色','配置初始好感度','填写开局大纲','确认开局'][page];
  el('step').textContent='步骤 '+(page+1)+' / 4';
  el('prev').hidden=page===0;
  el('next').hidden=page===3;
  el('submit').hidden=page!==3;
  el('next').disabled=!ready;
  el('retry').hidden=ready;
  if(page===1)renderFavor();
  if(page===3)el('preview').textContent=buildText();
}
async function load(){
  if(busy)return;
  busy=true;ready=false;
  el('retry').disabled=true;
  try{
    openingOnly();
    await Promise.race([
      waitGlobalInitialized('Mvu'),
      new Promise((_,reject)=>setTimeout(()=>reject(Error('等待MVU超时，请重新加载。')),12000))
    ]);
    const data=await read();
    const entries=await getWorldbook(BOOK);
    const entry=entries.find(item=>item.name===ROSTER);
    if(!entry)throw Error('找不到共用名单。');
    const parsed=JSON.parse(entry.content.trim());
    if(!Array.isArray(parsed))throw Error('共用名单不是JSON数组。');

    const names=new Set();
    for(const person of parsed){
      const name=person.名字;
      if(typeof name!=='string'||!name||names.has(name))
        throw Error('共用名单存在无效或重复姓名。');
      names.add(name);
      const character=data.stat_data.角色[name];
      if(!character||!Number.isFinite(character.好感度)
         ||typeof character.出场!=='boolean')
        throw Error(name+'的角色变量不完整。');
    }

    roster=parsed;
    selected.clear();favorSelected.clear();values.clear();configured.clear();
    updateBatchToolbar();
    for(const person of roster){
      const character=data.stat_data.角色[person.名字];
      values.set(person.名字,character.好感度);
      if(character.出场)selected.add(person.名字);
    }
    const previous=data[META];
    // 恢复此面板已配置的好感度；兼容旧版提交记录。
    const favorNames=previous?.favorNames??Object.keys(previous?.applied??{})
      .filter(name=>Object.hasOwn(previous.applied[name],'好感度'));
    for(const name of favorNames)if(names.has(name))configured.add(name);
    el('outline').value=typeof previous?.outline==='string'?previous.outline:'';
    ready=true;page=0;
    renderPeople();show();
    el('status').textContent='已读取'+roster.length+'位角色，已选择'+selected.size+'位。';
  }catch(error){
    el('status').textContent=error.message;
    show();
  }finally{
    busy=false;el('retry').disabled=false;
  }
}

el('search').addEventListener('input',updateSearch);
el('favor-search').addEventListener('input',updateFavorSearch);

el('favor-batch-clear').addEventListener('click', () => {
  favorSelected.clear();
  for (const card of el('favor').children) {
    card.classList.remove('is-selected');
  }
  updateBatchToolbar();
  el('status').textContent = '已取消当前所有干员的多选。';
});

el('favor-batch-apply').addEventListener('click', () => {
  if (favorSelected.size === 0) {
    el('status').textContent = '请先点击角色卡图片，选择需要批量修改好感度的干员。';
    return;
  }
  const rawStr = el('favor-batch-val').value.trim();
  if (rawStr === '') {
    el('status').textContent = '请输入要批量录入的好感度数值 (-100 ~ 100)。';
    el('favor-batch-val').focus();
    return;
  }
  const rawVal = Number(rawStr);
  if (!Number.isFinite(rawVal) || !Number.isSafeInteger(rawVal)) {
    el('status').textContent = '好感度请输入有效整数（-100 ~ 100）。';
    return;
  }
  const finalVal = Math.max(-100, Math.min(100, rawVal));
  const count = favorSelected.size;
  for (const name of favorSelected) {
    configured.add(name);
    values.set(name, finalVal);
  }
  for (const card of el('favor').children) {
    const name = card.dataset.person;
    if (favorSelected.has(name)) {
      const input = card.querySelector('input[type=number]');
      if (input) input.value = String(finalVal);
      card.classList.remove('is-selected');
    }
  }
  favorSelected.clear();
  updateBatchToolbar();
  el('favor-batch-val').value = '';
  el('status').textContent = '已成功将好感度 ' + finalVal + ' 批量录入至 ' + count + ' 位干员，已自动取消多选。';
});

el('favor-batch-val').addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    el('favor-batch-apply').click();
  }
});

el('retry').addEventListener('click',load);
el('prev').addEventListener('click',()=>{if(!busy){page--;show();}});
el('next').addEventListener('click',()=>{
  try{
    if(busy||!ready)return;
    if(page===1)validate();
    if(page===2&&!el('outline').value.trim())throw Error('请填写开局大纲。');
    page++;show();el('status').textContent='';
  }catch(error){el('status').textContent=error.message;}
});

el('submit').addEventListener('click',async()=>{
  if(busy)return;
  let wrote=false;
  busy=true;
  el('submit').disabled=true;el('prev').disabled=true;
  try{
    openingOnly();
    const text=buildText();
    const box=inputBox();
    const current=await read();
    const oldMeta=current[META];
    if(box.value.trim()&&box.value!==oldMeta?.text)
      throw Error('聊天输入框已有其他文字，请先保存或清空，再提交。');

    const data=structuredClone(current);
    const characters=data.stat_data.角色;
    const baseline=oldMeta?.baseline||{};
    const last=oldMeta?.applied||{};

    // 先检查上次设置之后，有没有其他地方改动同一字段。
    for(const [name,fields] of Object.entries(last)){
      for(const [field,value] of Object.entries(fields)){
        if(!Object.is(characters[name]?.[field],value))
          throw Error(name+'的'+field+'已在其他地方改变。请新建聊天，避免覆盖。');
      }
    }
    // 撤回本面板上一次提交的修改。
    for(const [name,fields] of Object.entries(baseline)){
      if(!characters[name])throw Error('角色变量缺失：'+name);
      for(const [field,value] of Object.entries(fields))
        characters[name][field]=value;
    }

    const newBaseline={},applied={};
    function change(name,field,value){
      const character=characters[name];
      if(!character)throw Error('角色变量缺失：'+name);
      if(Object.is(character[field],value))return;
      (newBaseline[name]??={})[field]=character[field];
      (applied[name]??={})[field]=value;
      character[field]=value;
    }

    // 只有选中的角色在场；其余角色关闭出场并清空旧心里话。
    for(const person of roster){
      const name=person.名字,on=selected.has(name);
      change(name,'出场',on);
      if(configured.has(name))change(name,'好感度',values.get(name));
      if(!on&&typeof characters[name].心里话==='string')
        change(name,'心里话','');
    }
    data[META]={
      baseline:newBaseline,applied,text,favorNames:[...configured],
      outline:el('outline').value.trim()
    };

    openingOnly();
    await Mvu.replaceMvuData(data,scope);
    wrote=true;
    const actual=await read();
    for(const person of roster){
      const name=person.名字,character=actual.stat_data.角色[name];
      if(character?.出场!==selected.has(name))
        throw Error(name+'的出场状态核对失败。');
      if(configured.has(name)&&character.好感度!==values.get(name))
        throw Error(name+'的好感度核对失败。');
    }
    openingOnly();
    // 不将用户大纲作为斜杠命令执行。
    const target=inputBox();
    if(target.value.trim()&&target.value!==oldMeta?.text)
      throw Error('提交期间输入框发生变化，未覆盖文字。');
    target.value=text;
    target.dispatchEvent(new window.parent.Event('input',{bubbles:true}));
    target.focus();
    el('status').textContent='变量已保存并核对，开局内容已填入输入框。\n检查后手动发送即可。仍可返回修改，再次提交。';
  }catch(error){
    el('status').textContent=(wrote
      ?'变量可能已经写入，但填入或核对未完成：'
      :'未完成提交：')+error.message;
  }finally{
    busy=false;
    el('submit').disabled=false;el('prev').disabled=false;
  }
});
await load();
})();
</script>
